<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Loopza Trace &amp; Find — Review Console | Nexora</title>
<style>
:root{color-scheme:light;--ink:#142238;--muted:#61718a;--line:#e2e8f0;--blue:#2457d6;--navy:#101d33;--paper:#f4f7fb}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}header{background:var(--navy);color:white;padding:18px 24px;display:flex;justify-content:space-between}header strong{font-size:19px}header small{display:block;color:#b9c7dc}main{max-width:1180px;margin:28px auto;padding:0 18px}.intro{margin-bottom:20px}.intro h1{margin:0;font-size:27px}.intro p,.muted{color:var(--muted)}.security,.panel{background:white;border:1px solid var(--line);border-radius:12px;padding:17px;margin-bottom:16px}.security p{margin:4px 0;color:var(--muted);font-size:13px}.tag{display:inline-block;padding:3px 8px;border-radius:20px;background:#edf2ff;color:#2449a5;font-size:11px;font-weight:700}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.tabs button,.secondary{border:1px solid var(--line);background:white;border-radius:8px;padding:10px 13px;cursor:pointer}.tabs button[aria-selected=true]{background:var(--navy);color:white}.primary{background:var(--blue);color:white;border:0;border-radius:8px;padding:10px 14px;font-weight:700;cursor:pointer}.panel-head,.item{display:flex;justify-content:space-between;gap:12px;align-items:center}.panel h2{font-size:18px;margin:0}.notice{padding:10px 12px;border-radius:8px;background:#f1f5f9;margin:12px 0}.notice.error{background:#fff1f0;color:#b42318}.notice.success{background:#ecfdf3;color:#16794b}.otp{display:none;background:#f6f8ff;border:1px solid #c8d6f4;border-radius:10px;padding:14px;margin:14px 0}.otp input{padding:10px;border:1px solid #cbd5e1;border-radius:8px;font:inherit}.items{display:grid;gap:10px}.item{border:1px solid var(--line);border-radius:10px;padding:14px;flex-wrap:wrap}.item h3{margin:0 0 4px;font-size:15px}.item p{margin:2px 0;color:var(--muted);font-size:13px}.detail{display:none;flex-basis:100%;border-top:1px solid var(--line);padding-top:12px}.detail textarea{display:block;width:100%;min-height:70px;margin:8px 0;border:1px solid var(--line);border-radius:8px;padding:10px;font:inherit}.detail select{padding:9px;border:1px solid var(--line);border-radius:8px}.empty{padding:32px;text-align:center;color:var(--muted)}footer{text-align:center;padding:26px;color:var(--muted);font-size:12px}@media(max-width:650px){main{margin:18px auto}.panel-head{align-items:flex-start;flex-direction:column}}
</style></head><body>
<header><div><strong>NEXORA</strong><small>Loopza Trace &amp; Find · Restricted review workspace</small></div><span class="tag">STAFF ACCESS ONLY</span></header>
<main><section class="intro"><h1>Human review console</h1><p>Review family profiles, case submissions and vetted access applications.</p></section>
<section class="security"><strong>Protected by Nexora Group staff verification</strong><p>Each queue read and decision requires a fresh, purpose-specific OTP. Your staff phone must already be approved by the organisation.</p></section>
<nav class="tabs"><button data-queue="profiles" aria-selected="true">Family profiles</button><button data-queue="cases" aria-selected="false">Case submissions</button><button data-queue="applications" aria-selected="false">Access applications</button></nav>
<section class="panel"><div class="panel-head"><h2 id="queueTitle">Family profile queue</h2><button class="primary" id="loadQueue">Verify &amp; load queue</button></div>
<div id="message" class="notice" role="status">Verify with your approved staff OTP to view restricted records.</div>
<div id="otpPanel" class="otp"><label for="otpCode">Six-digit code sent to your approved staff phone</label><p><input id="otpCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6"></p><button class="primary" id="verifyOtp">Verify and continue</button> <button class="secondary" id="cancelOtp">Cancel</button></div>
<div class="items" id="queueItems" aria-live="polite"></div></section></main><footer>Nexora Group · Access is logged. Do not disclose restricted information outside authorised workflows.</footer>
<script>
(()=>{const csrf=document.querySelector('meta[name="csrf-token"]').content;const $=id=>document.getElementById(id);let queue='profiles',pending=null,challengeId=null;
const urls={profiles:'/trace-find/review/profiles',cases:'/trace-find/review/cases',applications:'/trace-find/review/access-applications'};
const purposes={profiles:'loopza.trace.review.profiles.queue',cases:'loopza.trace.review.cases.queue',applications:'loopza.trace.access_applications.queue'};
const titles={profiles:'Family profile queue',cases:'Case submission queue',applications:'Vetted access applications'};
const say=(s,k)=>{$('message').textContent=s;$('message').className='notice'+(k?' '+k:'')};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,opts={}){const r=await fetch(url,{credentials:'same-origin',...opts,headers:{Accept:'application/json','X-CSRF-TOKEN':csrf,...(opts.headers||{})}});const d=await r.json().catch(()=>({message:'Unexpected server response'}));if(!r.ok)throw Error(d.message||Object.values(d.errors||{}).flat().join(' ')||('Request failed '+r.status));return d}
function otp(action,purpose){pending={action,purpose};challengeId=null;$('otpCode').value='';$('otpPanel').style.display='block';$('verifyOtp').disabled=true;say('Requesting a fresh one-time code…');api('/group/staff-security/otp/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({purpose})}).then(d=>{challengeId=d.challenge_id;$('verifyOtp').disabled=false;say(d.message+' Enter the code to continue.','success')}).catch(e=>{$('otpPanel').style.display='none';pending=null;say(e.message,'error')})}
$('verifyOtp').onclick=async()=>{if(!challengeId||!pending)return;const code=$('otpCode').value.trim();if(!/^\d{6}$/.test(code)){say('Enter the six-digit code.','error');return}$('verifyOtp').disabled=true;try{await api('/group/staff-security/otp/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge_id:challengeId,code})});$('otpPanel').style.display='none';const fn=pending.action;pending=null;await fn()}catch(e){say(e.message,'error');$('verifyOtp').disabled=false}};
$('cancelOtp').onclick=()=>{$('otpPanel').style.display='none';pending=null;challengeId=null;say('Verification cancelled.')};
async function load(){const d=await api(urls[queue]);const rows=d.data||[];$('queueItems').innerHTML='';if(!rows.length){$('queueItems').innerHTML='<div class="empty">No records are awaiting review.</div>';return}
rows.forEach(row=>{const id=esc(row.id),el=document.createElement('article');el.className='item';let title='',sub='',detail='';
if(queue==='profiles'){title='Profile #'+id+' · '+esc(row.user?.name);sub=esc(row.country_code)+' · '+esc(row.region_code||'Region not supplied')+' · phone ending '+esc(row.user?.phone_last_four||'—')+'<br>Identity: '+esc(row.identity_status)+' · Location: '+esc(row.location_status)+' · Selfie: '+esc(row.selfie_status);detail='<p>Review each component separately. Submitted coordinates are evidence, not proof of physical presence.</p><select id="i-'+id+'"><option value="approved">Identity approved</option><option value="rejected">Identity rejected</option></select> <select id="l-'+id+'"><option value="approved">Location approved</option><option value="rejected">Location rejected</option></select> <select id="s-'+id+'"><option value="approved">Selfie approved</option><option value="rejected">Selfie rejected</option></select><textarea id="n-'+id+'" placeholder="Review notes"></textarea><button class="primary" data-action="profile" data-id="'+id+'">Submit decision · OTP required</button>'}
else if(queue==='cases'){title=esc(row.reference_number||('Case #'+id));sub='Status: '+esc(row.status)+' · '+esc(row.country_code||'Country not supplied');detail='<select id="d-'+id+'"><option value="approve">Approve pending publication</option><option value="reject">Reject</option><option value="request_information">Request more information</option></select><textarea id="n-'+id+'" placeholder="Reason / instructions for reporter" required></textarea><button class="primary" data-action="case" data-id="'+id+'">Submit decision · OTP required</button>'}
else{title='Application #'+id+' · '+esc(row.applicant?.name);sub=esc(row.requested_role)+' · '+esc(row.country_code)+' · '+esc(row.status)+'<br>'+esc(row.organisation_name||'Volunteer application');detail='<p>'+esc(row.credentials_summary||'')+'</p><select id="d-'+id+'"><option value="approve">Approve vetting only</option><option value="reject">Reject</option><option value="request_information">Request more information</option></select><textarea id="n-'+id+'" placeholder="Review rationale (minimum 5 characters)" required></textarea><button class="primary" data-action="application" data-id="'+id+'">Submit decision · OTP required</button>'}
el.innerHTML='<div><h3>'+title+'</h3><p>'+sub+'</p></div><button class="secondary" data-toggle="'+id+'">Review</button><div class="detail" id="detail-'+id+'">'+detail+'</div>';$('queueItems').appendChild(el)})}
$('queueItems').onclick=e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.id||b.dataset.toggle;if(b.dataset.toggle){const d=$('detail-'+id);d.style.display=d.style.display==='block'?'none':'block';return}const action=b.dataset.action;let data,purpose,url;if(action==='profile'){data={identity_decision:$('i-'+id).value,location_decision:$('l-'+id).value,selfie_decision:$('s-'+id).value,notes:$('n-'+id).value};purpose='loopza.trace.review.profile.'+id;url='/trace-find/review/profiles/'+id+'/decision'}else if(action==='case'){data={decision:$('d-'+id).value,notes:$('n-'+id).value};purpose='loopza.trace.review.case.'+id;url='/trace-find/review/cases/'+id+'/decision'}else{data={decision:$('d-'+id).value,notes:$('n-'+id).value};purpose='loopza.trace.access_applications.decision.'+id;url='/trace-find/review/access-applications/'+id+'/decision'}otp(async()=>{await api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});say('Decision saved and audited.','success');await load()},purpose)};
$('loadQueue').onclick=()=>otp(load,purposes[queue]);document.querySelectorAll('[data-queue]').forEach(b=>b.onclick=()=>{queue=b.dataset.queue;document.querySelectorAll('[data-queue]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$('queueTitle').textContent=titles[queue];$('queueItems').innerHTML='';say('Select “Verify & load queue” to request a fresh OTP for this queue.')});
})();
</script></body></html>